}

public func start() {
    guard geometryTask == nil else { return }
    geometryTask = Task { [weak self] in
        await self?.loadGeometry()
    }
}

public func stop() {
    geometryTask?.cancel()
    streamTask?.cancel()
    geometryTask = nil
    streamTask = nil
}

