struct ViewportModelTests {
    private let address = RobotAddress(host: "127.0.0.1")

    /// Attaching alone starts nothing — the viewport has to be on screen first.
    @Test("nothing runs until the viewport is active")
    func inactiveStartsNothing() {
        let model = ViewportModel()
        model.attach(to: address)
        #expect(model.sceneModel == nil)
        #expect(model.cameraSession == nil)
        model.detach()
    }

    @Test("re-attaching to the same address keeps the loaded scene")
    func attachIsIdempotent() throws {
        let model = ViewportModel()
        model.setActive(true)
        model.attach(to: address)
        let scene = try #require(model.sceneModel)

        model.attach(to: address)
        #expect(model.sceneModel === scene)

        model.attach(to: RobotAddress(host: "127.0.0.2"))
        #expect(model.sceneModel !== scene)
        model.detach()
    }

    @Test("switching to the camera keeps the scene in memory")
    func switchingKeepsScene() throws {
        let model = ViewportModel()
        model.setActive(true)
        model.attach(to: address)
        let scene = try #require(model.sceneModel)

        model.setContent(.camera)
        #expect(model.cameraSession != nil)
        // Paused, not discarded: coming back must not re-download the geometry.
        #expect(model.sceneModel === scene)

        model.setContent(.scene)
        #expect(model.sceneModel === scene)
        // The peer connection is the expensive thing, and it does not survive.
        #expect(model.cameraSession == nil)
        model.detach()
    }

    @Test("leaving the viewport drops the camera and keeps the scene")
    func suspendDropsCameraOnly() throws {
        let model = ViewportModel()
        model.setActive(true)
        model.attach(to: address)
        model.setContent(.camera)
        let scene = try #require(model.sceneModel)

        model.setActive(false)
        #expect(model.cameraSession == nil)
        #expect(model.sceneModel === scene)

        model.setActive(true)
        #expect(model.cameraSession != nil)
        #expect(model.sceneModel === scene)
        model.detach()
    }

    @Test("detach is idempotent and clears both engines")
    func detachIsIdempotent() {
        let model = ViewportModel()
        model.setActive(true)
        model.attach(to: address)
        model.detach()
        model.detach()
        #expect(model.sceneModel == nil)
        #expect(model.cameraSession == nil)
    }
}

import RealityKit

/// Three-point lighting rig for the robot viewer.
///
/// A non-AR `RealityView` has no environment probe, so physically based materials
/// render black until something illuminates them. Directional lights are enough
/// here — the robot is a single small object viewed from outside.
@MainActor
public enum RobotSceneLighting {
    /// Key light carries the shading; fill opens the shadows; rim separates the
    /// silhouette from the background.
    public static func makeRig() -> Entity {
        let rig = Entity()
        rig.name = "lighting"
        rig.addChild(makeLight(named: "key", intensity: 2500, from: [0.6, 0.9, 0.8], castsShadow: true))
        rig.addChild(makeLight(named: "fill", intensity: 800, from: [-0.8, 0.2, 0.5], castsShadow: false))
        rig.addChild(makeLight(named: "rim", intensity: 600, from: [0, 0.4, -1.0], castsShadow: false))
        return rig
    }

    private static func makeLight(
        named name: String,
        intensity: Float,
        from position: SIMD3<Float>,
        castsShadow: Bool
    ) -> DirectionalLight {
        let light = DirectionalLight()
        light.name = name
        light.light.intensity = intensity
        // Three shadow casters muddy the image and cost fill rate for nothing, so
        // only the key light gets one. Reading `light.shadow` back is misleading:
        // it synthesises a default when the component is absent.
        if castsShadow {
            light.shadow = .init()
        }
        light.look(at: .zero, from: position, relativeTo: nil)
        return light
    }
}

