/// TEMPORARY diagnostic harness — delete once the viewport swap bug is understood.
///
/// Reproduces the shape of `ViewportView`'s 3D/camera switch with nothing but a box:
/// entities owned outside the view, a `RealityView` destroyed and rebuilt by a
/// `ViewBuilder` branch. If the box also vanishes on the first return, the fault is
/// in that pattern rather than anywhere in the robot scene.
@MainActor
final class SwapHarnessScene {
    static let shared = SwapHarnessScene()

    let container = Entity()
    let camera = PerspectiveCamera()

    private init() {
        let box = ModelEntity(
            mesh: .generateBox(size: 0.2),
            materials: [SimpleMaterial(color: .red, isMetallic: false)]
        )
        container.addChild(box)
        let light = DirectionalLight()
        light.light.intensity = 2500
        light.look(at: .zero, from: [0.6, 0.9, 0.8], relativeTo: nil)
        container.addChild(light)
        camera.look(at: .zero, from: [0, 0, 0.6], relativeTo: nil)
    }
}

struct RealityViewSwapHarness: View {
    @State private var showsScene = true
    @State private var makeCount = 0

    var body: some View {
        VStack(spacing: 0) {
            Picker("Content", selection: $showsScene) {
                Text("3D").tag(true)
                Text("Other").tag(false)
            }
            .pickerStyle(.segmented)
            .padding()

            Text("make: ran \(makeCount)x")
                .font(.caption.monospaced())

            if showsScene {
                RealityView { content in
                    content.entities.append(SwapHarnessScene.shared.container)
                    content.entities.append(SwapHarnessScene.shared.camera)
                    makeCount += 1
                } update: { _ in }
            } else {
                Color.gray.overlay(Text("stand-in for the camera").foregroundStyle(.white))
            }
        }
    }
}

