public var body: some View {
    RealityView { content in
        content.entities.append(model.container)
        // The scene supplies its own camera, so RealityKit's built-in controls
        // are off — they frame the scene once, at a point where the robot has
        // not downloaded yet.
        content.entities.append(model.camera.entity)
        SwapDiagnostics.shared.recordMake(container: model.container)
    } update: { content in
        // TEMPORARY: reparenting under a fresh root, which — unlike
        // `removeFromParent()` on a scene root — is a real move.
        guard reparentToken > 0 else { return }
        let root = Entity()
        root.name = "reparent-probe"
        root.addChild(model.container)
        root.addChild(model.camera.entity)
        content.entities.append(root)
        SwapDiagnostics.shared.reparents += 1
    }
    .gesture(orbit)
    .simultaneousGesture(zoom)
    .overlay(alignment: .bottomLeading) { diagnostics }
